export function validateCoreApiAskResponse(value: unknown): ValidationResult<CoreApiAskResponse> {
  const errors = validate(CORE_API_ASK_RESPONSE_JSON_SCHEMA, value)
  // The schema check above is what makes this narrowing sound.
  return errors.length === 0 ? { ok: true, value: value as CoreApiAskResponse } : { ok: false, errors }
}

